import assert from "node:assert/strict";
import { test } from "node:test";

import { isLoggedIn } from "./login.ts";

test("a login is valid until its token expires", () => {
  const session = { userId: "u1", accessToken: "fake", expiresAt: 2_000 };
  assert.equal(isLoggedIn(session, 1_000), true);
  assert.equal(isLoggedIn(session, 3_000), false);
});
